import marshmallow
from marshmallow import Schema, fields

# Test 1: Passing an invalid value to Schema.__init__ should raise ValueError after PR
class MySchema(Schema):
    foo = fields.String()

try:
    s = MySchema(unknown='badval')
    print('No error raised for init')
except ValueError as e:
    print(f'ValueError raised for init: {e}')

# Test 2: Passing an invalid value to Schema.load should raise ValueError after PR
try:
    MySchema().load({'foo': 'bar'}, unknown='badval')
    print('No error raised for load')
except ValueError as e:
    print(f'ValueError raised for load: {e}')

from marshmallow.validate import URL

validator = URL()

# Test 1: URL with only password (no username) - should be valid per RFC 3986
try:
    result = validator("http://:pass@example.com")
    print("http://:pass@example.com -> VALID")
except Exception as e:
    print(f"http://:pass@example.com -> INVALID: {e}")

# Test 2: URL with no userinfo at all but @ present - should be valid per RFC 3986
try:
    result = validator("http://@example.com")
    print("http://@example.com -> VALID")
except Exception as e:
    print(f"http://@example.com -> INVALID: {e}")

# Test 3: URL with multiple @ signs - should be invalid
try:
    result = validator("http://user@pass@example.com")
    print("http://user@pass@example.com -> VALID")
except Exception as e:
    print(f"http://user@pass@example.com -> INVALID: {e}")

# Test 4: URL with special RFC 3986 allowed chars in userinfo
try:
    result = validator("http://AZaz09-._~%2A!$&'()*+,;=:@example.com")
    print("http://AZaz09-._~%2A!$&'()*+,;=:@example.com -> VALID")
except Exception as e:
    print(f"http://AZaz09-._~%2A!$&'()*+,;=:@example.com -> INVALID: {e}")

