import marshmallow.utils as utils

# Test that a very large timestamp raises ValueError instead of OverflowError
try:
    result = utils.from_timestamp(99999999999999999)
    print('No error raised, result:', result)
except ValueError as e:
    print('ValueError:', e)
except OverflowError as e:
    print('OverflowError:', e)
except OSError as e:
    print('OSError:', e)

